INSERT IGNORE INTO screen_intro (id, screen_code, region, text_vi, audio_url, status, updated_at) VALUES
('DN-F07-BD-01', 'F-07', 'BD', 'Trên Bến Đò Ông Tư có ghe hàng đang đậu kìa! Con nghe khách đặt rồi chọn đúng giỏ giao nha!', NULL, 'draft', NOW()),
('DN-F07-BD-02', 'F-07', 'BD', 'Khách bên bờ sông đang gọi đặt hàng mang sang Cù Lao. Con nghe kỹ số lượng rồi chọn giỏ nhé!', NULL, 'draft', NOW()),
('DN-F07-BD-03', 'F-07', 'BD', 'Sương sớm trên sông đã dịu rồi! Con nghe đơn hàng của khách và chọn giỏ chuẩn cùng Cowdi nha!', NULL, 'draft', NOW()),
('DN-F07-BD-04', 'F-07', 'BD', 'Ông Tư cổ vũ con giao đủ sáu đơn hàng thật nhanh trên bến gỗ. Giữ nút loa để nghe chậm nhé!', NULL, 'draft', NOW()),
('DN-F07-TG-01', 'F-07', 'TG', 'Dưới chân Tháp Gió có phiên chợ nhỏ thật vui! Con nghe kỹ đơn hàng rồi chọn đúng giỏ nhé!', NULL, 'draft', NOW()),
('DN-F07-TG-02', 'F-07', 'TG', 'Mimi đứng đếm giúp con số lượng từng món trên cánh đồng Tháp Gió. Nghe thật rõ rồi chọn nha!', NULL, 'draft', NOW()),
('DN-F07-TG-03', 'F-07', 'TG', 'Owlbert nhắc con chú ý cả tên món và số lượng nhé! Cùng Cowdi giao chuẩn từng giỏ hàng nào!', NULL, 'draft', NOW()),
('DN-F07-TG-04', 'F-07', 'TG', 'Storm mang đơn hàng theo làn gió Tháp Gió tới rồi! Con lắng nghe rồi chọn giỏ thật nhanh nha!', NULL, 'draft', NOW()),
('DN-F07-VS-01', 'F-07', 'VS', 'Giữa Vườn Sữa xanh mát, khách đang gọi đặt từng giỏ hàng kìa! Con nghe rõ rồi chọn đúng nhé!', NULL, 'draft', NOW()),
('DN-F07-VS-02', 'F-07', 'VS', 'Bamboo chuẩn bị sẵn bốn giỏ hàng bên rừng trúc Vườn Sữa. Nghe thật kỹ số lượng cùng bò nha!', NULL, 'draft', NOW()),
('DN-F07-VS-03', 'F-07', 'VS', 'Đàn gà ở Vườn Sữa đứng xem con chọn giỏ hàng đấy! Nghe số đếm rồi chạm đúng giỏ nhé!', NULL, 'draft', NOW()),
('DN-F07-VS-04', 'F-07', 'VS', 'Cowdi và Bamboo Spirit cổ vũ con hoàn thành đủ sáu lượt nghe đếm số lượng tại Vườn Sữa nha!', NULL, 'draft', NOW()),
('DN-F10-BD-01', 'F-10', 'BD', 'Ông Tư đang ngồi chờ trò chuyện cùng con trên bến gỗ Bến Đò! Nghe câu hỏi rồi đáp lại nhé!', NULL, 'draft', NOW()),
('DN-F10-BD-02', 'F-10', 'BD', 'Chiếc đò ngang sang Cù Lao êm ả lắm, rất hợp luyện hội thoại tiếng Anh cùng ông Tư và bò nha!', NULL, 'draft', NOW()),
('DN-F10-BD-03', 'F-10', 'BD', 'Sương sớm trên mặt sông làm cuộc trò chuyện thêm ấm áp. Con nghe kỹ câu hỏi rồi tự tin đáp nhé!', NULL, 'draft', NOW()),
('DN-F10-BD-04', 'F-10', 'BD', 'Mỗi câu trả lời rõ ràng giúp ông Tư hiểu tiếng Anh hơn đấy! Cùng Cowdi trò chuyện thật vui nha!', NULL, 'draft', NOW()),
('DN-F10-TG-01', 'F-10', 'TG', 'Dưới bóng cánh quạt Tháp Gió, cùng bò luyện đối đáp tiếng Anh thật tự nhiên qua từng câu hỏi nhé!', NULL, 'draft', NOW()),
('DN-F10-TG-02', 'F-10', 'TG', 'Mimi và Owlbert đang lắng nghe màn hội thoại của con tại Tháp Gió đấy! Tự tin trả lời to rõ nha!', NULL, 'draft', NOW()),
('DN-F10-TG-03', 'F-10', 'TG', 'Gió lộng trên cánh đồng Tháp Gió mang theo câu hỏi mới. Con nghe kỹ rồi đáp theo gợi ý cùng bò nhé!', NULL, 'draft', NOW()),
('DN-F10-TG-04', 'F-10', 'TG', 'Storm cổ vũ con nói trọn vẹn câu trả lời tại Tháp Gió. Bấm nghe lại câu hỏi nếu con cần nha!', NULL, 'draft', NOW()),
('DN-F10-VS-01', 'F-10', 'VS', 'Giữa Vườn Sữa yên bình, cùng Cowdi trò chuyện tiếng Anh thật tự tin qua từng lượt hỏi đáp nhé!', NULL, 'draft', NOW()),
('DN-F10-VS-02', 'F-10', 'VS', 'Bên rừng trúc Vườn Sữa, Bamboo chăm chú nghe con trả lời từng câu hỏi tiếng Anh đấy! Bắt đầu nha!', NULL, 'draft', NOW()),
('DN-F10-VS-03', 'F-10', 'VS', 'Đàn gà ở Vườn Sữa đang trật tự nghe con tập hội thoại rồi! Nói to, rõ theo gợi ý cùng bò nhé!', NULL, 'draft', NOW()),
('DN-F10-VS-04', 'F-10', 'VS', 'Bamboo Spirit gửi tặng con những câu giao tiếp gần gũi tại Vườn Sữa. Nghe câu hỏi rồi đáp ngay nha!', NULL, 'draft', NOW()),
('DN-F11-BD-01', 'F-11', 'BD', 'Trên bến gỗ Bến Đò Ông Tư có xấp thẻ Đúng hay Sai kìa! Con đọc kỹ câu rồi chọn nhanh nhé!', NULL, 'draft', NOW()),
('DN-F11-BD-02', 'F-11', 'BD', 'Ông Tư nhờ con kiểm tra xem mấy câu tiếng Anh này đúng hay sai trước khi đò sang Cù Lao nha!', NULL, 'draft', NOW()),
('DN-F11-BD-03', 'F-11', 'BD', 'Chạm vào câu để nghe đọc giữa tiếng sóng sông Bến Đò, rồi vuốt trái hoặc phải thật gọn gàng nhé!', NULL, 'draft', NOW()),
('DN-F11-BD-04', 'F-11', 'BD', 'Sương sớm Bến Đò sẽ tan nhanh khi con phân biệt chuẩn từng thẻ Đúng hay Sai cùng Cowdi nha!', NULL, 'draft', NOW()),
('DN-F11-TG-01', 'F-11', 'TG', 'Gió Tháp Gió thổi tới xấp thẻ Đúng hay Sai mới tinh! Con đọc cẩn thận rồi chọn đáp án nhé!', NULL, 'draft', NOW()),
('DN-F11-TG-02', 'F-11', 'TG', 'Owlbert kiểm tra xem con nhận ra câu nào đúng, câu nào sai tại Tháp Gió đấy! Chạm hoặc vuốt thẻ nha!', NULL, 'draft', NOW()),
('DN-F11-TG-03', 'F-11', 'TG', 'Mimi đứng cổ vũ con dưới chân Tháp Gió. Đọc kỹ nghĩa từng câu rồi bấm nút Đúng hay Sai nhé!', NULL, 'draft', NOW()),
('DN-F11-TG-04', 'F-11', 'TG', 'Storm bảo chỉ cần đọc kỹ từng chữ là vượt gọn màn Đúng hay Sai ở Tháp Gió. Thử cùng bò nha!', NULL, 'draft', NOW()),
('DN-F11-VS-01', 'F-11', 'VS', 'Giữa Vườn Sữa xanh mát, cùng Cowdi đọc từng tấm thẻ và phân biệt thật chuẩn Đúng hay Sai nhé!', NULL, 'draft', NOW()),
('DN-F11-VS-02', 'F-11', 'VS', 'Bamboo đặt sẵn bộ thẻ Đúng hay Sai bên rừng trúc Vườn Sữa. Con vuốt trái là Sai, phải là Đúng nha!', NULL, 'draft', NOW()),
('DN-F11-VS-03', 'F-11', 'VS', 'Đàn gà ở Vườn Sữa tò mò xem con chọn đúng hết không kìa! Chạm vào câu để nghe phát âm nhé!', NULL, 'draft', NOW()),
('DN-F11-VS-04', 'F-11', 'VS', 'Bamboo Spirit sẵn sàng giải thích ngay nếu con chọn nhầm tại Vườn Sữa. Đọc kỹ rồi trả lời cùng bò nha!', NULL, 'draft', NOW());
